WITH filtered AS (SELECT *, SUBSTRING(city, 1, 2) city_prefix, COALESCE(city, 'NONE') city_clean FROM suppliers WHERE city IS NOT NULL AND city IS NOT DISTINCT FROM 'Chiang Mai') SELECT id, country, city, rating, city_prefix, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) rating_avg_2, FIRST_VALUE(rating, TRUE) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_rating FROM filtered;
